 {
  \@ifpackageloaded{euler}
   {
    \bool_if:NTF \g__fontspec_pkg_euler_loaded_bool
     { \bool_gset_true:N \g__fontspec_math_euler_bool }
     { \__fontspec_error:n {euler-too-late} }
