  \FP@upnc@debug{\FP@valb-th #1 of \FP@vala}%
  \csname FP#1\endcsname\FP@valc\FP@vala\FP@valb%
  \FP@upnc@result{\FP@valc}%
  \FP@putstack\FP@valc%
}
\def\FP@binopd#1{%
  \FP@getstack\FP@vala\FP@getstack\FP@valb%
  \FP@upnc@debug{#1(\FP@valb,\FP@vala)}%
  \csname FP#1\endcsname\FP@valc\FP@vala\FP@valb%
  \FP@upnc@result{\FP@valc}%
  \FP@putstack\FP@valc%
