  \FP@putstack{#1}%
}

\defpattern\FP@upn[#2#3]{%
  \ifx#2\@undefined%
    \FP@upnc@debug{#2#3}%
    \expandafter\expandafter\expandafter\FP@put\csname #2#3\endcsname\@upnend%
