% The in-worker engine ships no hyphenation patterns, so polyglossia always
% takes its "no patterns" branch, which calls BABEL's \adddialect to link a
% language to \l@nohyphenation. Babel (which normally allocates both counts)
% is not loaded here, so provide a stand-in that reproduces babel's language
% allocation: give the new dialect its own \count and set it to the source
% language. When babel IS loaded, its real definition is used instead.
% The engine's format pre-defines some \l@<name> as \relax (an unguarded
% \csname side effect), so \ifdefined alone cannot be trusted: such names
% are unhooked and (re)allocated as if they were truly undefined. This
% matches polyglossia's own convention, which treats a \relax-let
% \l@<lang> as "not defined" (see \polyglossia@check@ifdefined:N below).
\ifx\adddialect\undefined
  \def\adddialect#1#2{%
    \ifdefined\l@nohyphenation\else
      \countdef\l@nohyphenation=\count@
      \l@nohyphenation=0\relax
    \fi
    \ifx#1\relax\let#1\undefined\fi
    \ifdefined#1\else\countdef#1=\count@\fi
    #1=#2\relax
  }
\fi
% The engine's format also omits babel's hyphenmins helpers (normally
% shipped in the format's hyphen.cfg); polyglossia's \setlocalhyphenmins
% and \use@localhyphenmins rely on them.
\ifx\providehyphenmins\undefined
  \def\providehyphenmins#1#2{%
    \expandafter\ifx\csname#1hyphenmins\endcsname\relax
      \@namedef{#1hyphenmins}{#2}%
    \fi}%
\fi
\ifx\set@hyphenmins\undefined
  \def\set@hyphenmins#1#2{%
    \lefthyphenmin#1\relax
    \righthyphenmin#2\relax}%
\fi
